using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using UnityEditor.SceneManagement;using OneWay.Battle3D;
public static class BuildPlayableNewAttacks
{
 const string Folder="Assets/3DBattle/NewPlayer/PlayableAttacks";
 class Pose{public Vector3[] p,s;public Quaternion[] q;}
 static Pose Read(Transform[] n)=>new Pose{p=n.Select(t=>t.localPosition).ToArray(),s=n.Select(t=>t.localScale).ToArray(),q=n.Select(t=>t.localRotation).ToArray()};
 static void Apply(Transform[] n,Pose p){for(int j=0;j<n.Length;j++){n[j].localPosition=p.p[j];n[j].localRotation=p.q[j];n[j].localScale=p.s[j];}}
 static void Blend(Transform[] n,Pose a,Pose b,float u){for(int j=0;j<n.Length;j++){n[j].localPosition=Vector3.Lerp(a.p[j],b.p[j],u);n[j].localRotation=Quaternion.Slerp(a.q[j],b.q[j],u);n[j].localScale=Vector3.Lerp(a.s[j],b.s[j],u);}}
 static float Floor(SkinnedMeshRenderer r){var mesh=r.sharedMesh;var v=mesh.vertices;var w=mesh.boneWeights;var m=r.bones.Select((b,i)=>b.localToWorldMatrix*mesh.bindposes[i]).ToArray();float y=float.MaxValue;for(int i=0;i<v.Length;i++){var a=w[i];var p=m[a.boneIndex0].MultiplyPoint3x4(v[i])*a.weight0+m[a.boneIndex1].MultiplyPoint3x4(v[i])*a.weight1+m[a.boneIndex2].MultiplyPoint3x4(v[i])*a.weight2+m[a.boneIndex3].MultiplyPoint3x4(v[i])*a.weight3;y=Mathf.Min(y,p.y);}return y;}
 static AnimationClip Write(string name,string[] paths,List<Pose> poses,float seconds)
 {
  var bs=new List<EditorCurveBinding>();var cs=new List<AnimationCurve>();for(int j=0;j<paths.Length;j++){for(int f=1;f<poses.Count;f++)if(Quaternion.Dot(poses[f-1].q[j],poses[f].q[j])<0){var q=poses[f].q[j];poses[f].q[j]=new Quaternion(-q.x,-q.y,-q.z,-q.w);}for(int c=0;c<10;c++){var curve=new AnimationCurve(poses.Select((p,f)=>new Keyframe(seconds*f/(poses.Count-1),c<3?p.p[j][c]:c<7?p.q[j][c-3]:p.s[j][c-7])).ToArray());for(int k=0;k<curve.length;k++){AnimationUtility.SetKeyLeftTangentMode(curve,k,AnimationUtility.TangentMode.Linear);AnimationUtility.SetKeyRightTangentMode(curve,k,AnimationUtility.TangentMode.Linear);}bs.Add(EditorCurveBinding.FloatCurve(paths[j],typeof(Transform),c<3?"m_LocalPosition."+"xyz"[c]:c<7?"m_LocalRotation."+"xyzw"[c-3]:"m_LocalScale."+"xyz"[c-7]));cs.Add(curve);}}
  var clip=new AnimationClip{name=name,frameRate=30};AnimationUtility.SetEditorCurves(clip,bs.ToArray(),cs.ToArray());var settings=AnimationUtility.GetAnimationClipSettings(clip);settings.loopTime=false;AnimationUtility.SetAnimationClipSettings(clip,settings);AssetDatabase.CreateAsset(clip,Folder+"/"+name+".anim");return clip;
 }
 static AnimationCurve Curve(List<Keyframe> keys){var c=new AnimationCurve(keys.ToArray());for(int k=0;k<c.length;k++){AnimationUtility.SetKeyLeftTangentMode(c,k,AnimationUtility.TangentMode.Linear);AnimationUtility.SetKeyRightTangentMode(c,k,AnimationUtility.TangentMode.Linear);}return c;}
 static void IK(Transform upper,Transform lower,Transform foot,Vector3 target){var origin=upper.position;float l1=Vector3.Distance(origin,lower.position),l2=Vector3.Distance(lower.position,foot.position);var dir=(target-origin).normalized;float d=Mathf.Clamp(Vector3.Distance(origin,target),Mathf.Abs(l1-l2)+.00001f,l1+l2-.00001f);var pole=Vector3.ProjectOnPlane(lower.position-origin,dir).normalized;if(pole.sqrMagnitude<.01f)pole=Vector3.ProjectOnPlane(Vector3.forward,dir).normalized;float x=(l1*l1-l2*l2+d*d)/(2*d);var knee=origin+dir*x+pole*Mathf.Sqrt(Mathf.Max(0,l1*l1-x*x));upper.rotation=Quaternion.FromToRotation(lower.position-origin,knee-origin)*upper.rotation;lower.rotation=Quaternion.FromToRotation(foot.position-lower.position,origin+dir*d-lower.position)*lower.rotation;}
 public static object Run()
 {
  if(Application.isPlaying)throw new Exception("Stop Play Mode");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.name!="3DBattleDebugScene")throw new Exception("Expected debug scene");if(GameObject.Find("New Player - Attack Combo"))throw new Exception("Already installed");foreach(var w in Resources.FindObjectsOfTypeAll<AnimationWindow>()){w.recording=false;w.previewing=false;}if(AnimationMode.InAnimationMode())AnimationMode.StopAnimationMode();
  if(AssetDatabase.IsValidFolder(Folder))throw new Exception("Output already exists");AssetDatabase.CreateFolder("Assets/3DBattle/NewPlayer","PlayableAttacks");
  string[] labels={"Attack","Charged_Upward_Slash","Double_Combo_Attack","Right_Hand_Sword_Slash","Skill_03","Weapon_Combo_1"};int[] start={0,21,0,8,0,3},chain={86,42,41,22,16,39};Vector2[][] hits={new[]{new Vector2(27,33)},new[]{new Vector2(34,42)},new[]{new Vector2(17,25),new Vector2(33,41)},new[]{new Vector2(14,22)},new[]{new Vector2(6,16)},new[]{new Vector2(31,39)}};
  var clips=labels.Select(n=>AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/3DBattle/NewPlayer/Attack/Recovery20/NewKnight_"+n+"_Return20.anim")).ToArray();var skillClone=GameObject.Find("Attack 05 - Skill_03(Clone)");if(skillClone!=null)clips[4]=skillClone.GetComponentInChildren<Animator>().runtimeAnimatorController.animationClips[0];
  var template=GameObject.Find("Attack 01 - Attack");var temp=UnityEngine.Object.Instantiate(template);temp.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var a=temp.GetComponentInChildren<Animator>();a.enabled=false;var skin=temp.GetComponentInChildren<SkinnedMeshRenderer>();var paths=AnimationUtility.GetCurveBindings(clips[0]).Select(b=>b.path).Distinct().OrderBy(p=>p.Count(x=>x=='/')).ToArray();var nodes=paths.Select(p=>a.transform.Find(p)).ToArray();var hip=nodes.First(t=>t.name=="Hips");var feet=new[]{nodes.First(t=>t.name=="LeftFoot"),nodes.First(t=>t.name=="RightFoot")};var upper=new[]{nodes.First(t=>t.name=="LeftUpperLeg"),nodes.First(t=>t.name=="RightUpperLeg")};var lower=new[]{nodes.First(t=>t.name=="LeftLowerLeg"),nodes.First(t=>t.name=="RightLowerLeg")};
  var idleSource=AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/3DBattle/NewPlayer/Attack/Recovery20/NewKnight_IdleReady.anim");idleSource.SampleAnimation(a.gameObject,0);hip.position+=Vector3.up*(.015f-Floor(skin));var idlePose=Read(nodes);Vector3 idleHip=hip.position;
  var set=ScriptableObject.CreateInstance<NewPlayerAttackSet>();set.name="NewPlayerAttackSet";set.attacks=new NewPlayerAttackSet.Motion[6];var report=new List<object>();var errors=new List<string>();Application.LogCallback log=(m,s,t)=>{if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors.Add(m);};Application.logMessageReceived+=log;
  try{
   set.idle=Write("NewPlayer_Idle",paths,new List<Pose>{Read(nodes),Read(nodes)},1f/30f);
   for(int i=0;i<6;i++){
    int sourceEnd=Mathf.RoundToInt(clips[i].length*30);int final=sourceEnd+(i==4?20:0)-start[i];var poses=new List<Pose>();var z=new List<Keyframe>();var x=new List<Keyframe>();var y=new List<Keyframe>();clips[i].SampleAnimation(a.gameObject,start[i]/30f);var origin=hip.position;Pose tail=null;Vector3 tailHip=Vector3.zero;float peak=0;
    for(int half=0;half<=final*2;half++){float frame=half*.5f,src=frame+start[i];if(src<=sourceEnd){clips[i].SampleAnimation(a.gameObject,src/30f);tail=Read(nodes);tailHip=hip.position;}else{Apply(nodes,idlePose);hip.position=new Vector3(tailHip.x,idleHip.y,tailHip.z);var target=Read(nodes);Blend(nodes,tail,target,Mathf.SmoothStep(0,1,(src-sourceEnd)/20));}
     var travel=hip.position-origin;travel.y=0;float airborne=i==5?Mathf.Max(0,Floor(skin)-.015f):0;peak=Mathf.Max(peak,airborne);hip.position+=new Vector3(idleHip.x-origin.x-travel.x,-airborne,idleHip.z-origin.z-travel.z);if(i!=5)hip.position+=Vector3.up*Mathf.Max(0,.015f-Floor(skin));
     poses.Add(Read(nodes));z.Add(new Keyframe(frame,travel.z));x.Add(new Keyframe(frame,travel.x));y.Add(new Keyframe(frame,airborne));
    }
    var clip=Write("NewPlayer_Attack"+(i+1).ToString("00"),paths,poses,final/30f);var m=new NewPlayerAttackSet.Motion{label=labels[i],clip=clip,sourceFirstFrame=start[i],sourceChainFrame=chain[i],chainFrame=chain[i]-start[i],damageWindows=hits[i].Select(w=>w-Vector2.one*start[i]).ToArray(),forward=Curve(z),sideways=Curve(x),jump=Curve(y)};set.attacks[i]=m;report.Add(new{motion=labels[i],source=AssetDatabase.GetAssetPath(clips[i]),first=start[i],queuedEnd=chain[i],final,originalJumpHeight=peak});
   }
   Func<Pose,Pose,string,NewPlayerAttackSet.Motion> link=(previous,next,name)=>{
    Apply(nodes,previous);var oldFeet=feet.Select(t=>t.position).ToArray();var oldRot=feet.Select(t=>t.rotation).ToArray();int oldLead=oldFeet[0].z>oldFeet[1].z?0:1;Apply(nodes,next);var newFeet=feet.Select(t=>t.position).ToArray();int newLead=newFeet[0].z>newFeet[1].z?0:1;bool swap=oldLead!=newLead;Vector3 shift=swap?oldFeet[oldLead]-newFeet[oldLead]:Vector3.zero;shift.y=0;hip.position+=shift;var end=Read(nodes);var targets=feet.Select(t=>t.position).ToArray();var rotations=feet.Select(t=>t.rotation).ToArray();var poses=new List<Pose>();var z=new List<Keyframe>();var x=new List<Keyframe>();
    for(int h=0;h<=10;h++){float t=h/10f,u=t*t*t*(t*(t*6-15)+10);Blend(nodes,previous,end,u);if(swap){var goals=new[]{Vector3.Lerp(oldFeet[0],targets[0],u),Vector3.Lerp(oldFeet[1],targets[1],u)};goals[newLead]+=Vector3.up*(.14f*16*t*t*(1-t)*(1-t));for(int leg=0;leg<2;leg++){IK(upper[leg],lower[leg],feet[leg],goals[leg]);feet[leg].rotation=Quaternion.Slerp(oldRot[leg],rotations[leg],u);}}
     var travel=hip.position-idleHip;travel.y=0;hip.position-=travel;poses.Add(Read(nodes));z.Add(new Keyframe(h*.5f,travel.z));x.Add(new Keyframe(h*.5f,travel.x));}
    return new NewPlayerAttackSet.Motion{label=name,clip=Write(name,paths,poses,5f/30f),chainFrame=5,damageWindows=new Vector2[0],forward=Curve(z),sideways=Curve(x)};
   };
   set.attacks[4].clip.SampleAnimation(a.gameObject,0);set.entry=link(idlePose,Read(nodes),"NewPlayer_Entry");set.links=new NewPlayerAttackSet.Motion[7];for(int seq=0;seq<7;seq++){var before=set.attacks[set.order[seq]];var after=set.attacks[set.order[(seq+1)%7]];before.clip.SampleAnimation(a.gameObject,before.chainFrame/30f);var p=Read(nodes);after.clip.SampleAnimation(a.gameObject,0);set.links[seq]=link(p,Read(nodes),"NewPlayer_Link"+(seq+1));}
   if(errors.Count>0)throw new Exception(string.Join("|",errors));AssetDatabase.CreateAsset(set,Folder+"/NewPlayerAttackSet.asset");var ctrl=AnimatorController.CreateAnimatorControllerAtPath(Folder+"/NewPlayerAttackCombo.controller");var sm=ctrl.layers[0].stateMachine;var idle=sm.AddState("Idle");idle.motion=set.idle;sm.defaultState=idle;foreach(var m in set.attacks.Concat(set.links).Concat(new[]{set.entry})){var state=sm.AddState(m.clip.name);state.motion=m.clip;}
   var original=UnityEngine.Object.FindFirstObjectByType<BattlePlayerController>();var oldChildren=original.GetComponentsInChildren<Component>(true);var go=UnityEngine.Object.Instantiate(original.gameObject,original.transform.parent);go.name="New Player - Attack Combo";Undo.RegisterCreatedObjectUndo(go,"Create attack-only NewPlayer");go.transform.SetPositionAndRotation(original.transform.position,original.transform.rotation);var pnew=go.GetComponent<BattlePlayerController>();UnityEngine.Object.DestroyImmediate(pnew.animator.gameObject);var visual=UnityEngine.Object.Instantiate(template,go.transform);visual.name="NewPlayer Visual";visual.transform.localPosition=Vector3.zero;visual.transform.localRotation=Quaternion.identity;visual.transform.localScale=Vector3.one;pnew.animator=visual.GetComponentInChildren<Animator>();pnew.animator.runtimeAnimatorController=ctrl;pnew.animator.applyRootMotion=false;pnew.animator.enabled=true;pnew.animator.speed=1;pnew.shield=null;
   var combo=go.AddComponent<NewPlayerAttackCombo>();combo.motions=set;var parry=go.GetComponent<BattleParryEffect>();if(parry!=null)parry.enabled=false;var slash=go.GetComponent<BattleSwordSlashEffect>();if(slash!=null)slash.sword=visual.GetComponentsInChildren<Transform>().First(t=>t.name=="Sword");set.idle.SampleAnimation(pnew.animator.gameObject,0);
   // Remap scene references to the new actor, leaving the preserved original hierarchy untouched.
   var remap=new Dictionary<UnityEngine.Object,UnityEngine.Object>{{original.gameObject,go},{original.transform,go.transform},{original,pnew},{original.GetComponent<BattlePlayerHealth>(),go.GetComponent<BattlePlayerHealth>()},{original.GetComponent<CharacterController>(),go.GetComponent<CharacterController>()},{original.animator,pnew.animator}};foreach(var c in original.GetComponents<Component>())if(!remap.ContainsKey(c)){var n=go.GetComponent(c.GetType());if(n)remap[c]=n;}
   int refs=0;foreach(var c in UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsInactive.Include,FindObjectsSortMode.None)){if(c==null||c.transform.IsChildOf(original.transform)||c.transform.IsChildOf(go.transform)||c.gameObject.scene!=scene)continue;var so=new SerializedObject(c);var prop=so.GetIterator();bool dirty=false;while(prop.Next(true)){if(prop.propertyType!=SerializedPropertyType.ObjectReference)continue;var v=prop.objectReferenceValue;if(v!=null&&remap.TryGetValue(v,out var replacement)){prop.objectReferenceValue=replacement;dirty=true;refs++;}}if(dirty)so.ApplyModifiedProperties();}
   Undo.RecordObject(original.gameObject,"Preserve previous player inactive");original.gameObject.SetActive(false);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var result=new{scene=scene.name,newPlayer=go.name,originalPreserved=true,remappedReferences=refs,order=set.order.Select(i=>labels[i]).ToArray(),attacks=report,errors=errors.ToArray()};System.IO.File.WriteAllText("Assets/3DBattle/Authoring~/PlayableNewAttacksReport.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));Selection.activeGameObject=go;return result;
  }finally{Application.logMessageReceived-=log;UnityEngine.Object.DestroyImmediate(temp);}
 }
}
